//! Local AI assistant (spec §7.10, roadmap D1/D6): plain-language answers
//! about the open file, generated by an open-source model running on this
//! machine (Ollama by default; any OpenAI-compatible local server works).
//!
//! The model only sees a compact FACTS block built from Drishti's own
//! static results (summary, findings, behaviours, document report, …); it
//! never sees or runs the file itself. Answers stream to the browser as
//! plain text.
//!
//! Safety:
//! - Plain `http://` to the configured server only. In server mode the URL
//!   comes from `DRISHTI_AI_URL` and is not settable over the API, so a
//!   client cannot point the server at arbitrary internal hosts.
//! - Facts are wrapped and labelled as untrusted data (strings and metadata
//!   are written by the file's author and may contain prompt injection).
//! - Output is rendered as text by the UI, never as HTML.

use crate::api::{ApiError, R, bad, session, valid_sha};
use crate::extra::{build_insights, origin_of};
use crate::state::{Session, Shared};
use axum::Json;
use axum::body::{Body, Bytes};
use axum::extract::{Path, State};
use axum::http::{Request, StatusCode, header};
use axum::response::Response;
use http_body_util::{BodyExt, Full};
use hyper_util::rt::TokioIo;
use serde::Deserialize;
use serde_json::{Value, json};
use std::time::Duration;


pub const DEFAULT_URL: &str = "http://127.0.0.1:11434";
const CONNECT_TIMEOUT: Duration = Duration::from_secs(3);
/// Loading a model into memory on first use can take a while.
const FIRST_BYTE_TIMEOUT: Duration = Duration::from_secs(180);
const MAX_ANSWER_SECS: u64 = 600;
const FACTS_BUDGET: usize = 9_000;

/// Models that answer well at small sizes, best first (prefix match).
const PREFERRED: &[&str] = &[
    "qwen3", "qwen2.5", "llama3.2", "llama3.1", "gemma3", "phi4", "mistral", "granite",
];

#[derive(Debug, Clone)]
pub struct AiConfig {
    pub url: String,
    pub provider: String,
    pub model: Option<String>,
    pub enabled: bool,
}

pub(crate) fn setting_str(st: &Shared, key: &str) -> Option<String> {
    let db = st.db.lock().ok()?;
    let v: String = db
        .query_row("SELECT value FROM settings WHERE key=?1", [key], |r| {
            r.get(0)
        })
        .ok()?;
    match serde_json::from_str::<Value>(&v) {
        Ok(Value::String(s)) => Some(s),
        Ok(Value::Bool(b)) => Some(b.to_string()),
        Ok(Value::Null) => None,
        _ => Some(v),
    }
    .filter(|s| !s.trim().is_empty())
}

pub fn config(st: &Shared) -> AiConfig {
    let env_url = std::env::var("DRISHTI_AI_URL")
        .ok()
        .filter(|s| !s.is_empty());
    let url = if st.local_mode {
        setting_str(st, "ai.url").or(env_url)
    } else {
        env_url
    }
    .unwrap_or_else(|| DEFAULT_URL.to_string());
    let url = url.trim().trim_end_matches('/').to_string();
    let provider = setting_str(st, "ai.provider")
        .or_else(|| std::env::var("DRISHTI_AI_PROVIDER").ok())
        .unwrap_or_else(|| {
            if url.ends_with(":11434") {
                "ollama".into()
            } else {
                "openai".into()
            }
        });
    AiConfig {
        url,
        provider,
        model: setting_str(st, "ai.model").or_else(|| std::env::var("DRISHTI_AI_MODEL").ok()),
        enabled: setting_str(st, "ai.enabled").as_deref() != Some("false"),
    }
}

