/// A cloud AI provider reached over HTTPS with the person's own API key.
pub struct Cloud {
    pub id: &'static str,
    pub name: &'static str,
    /// Chat endpoint (fixed: never configurable, so no SSRF).
    pub url: &'static str,
    pub models_url: Option<&'static str>,
    /// Suggested models, best default first (others can be typed in).
    pub suggested: &'static [&'static str],
    pub anthropic: bool,
}

